import assert from'node:assert/strict';import{mkdirSync,writeFileSync}from'node:fs';import{chromium,webkit}from'playwright';
import{displayedChapterCollections,chapterHash}from'../lib/practice-chapters.ts';
const base=process.env.KLINK_TEST_BASE||'http://127.0.0.1:18996',out=process.env.KLINK_TEST_OUTPUT||'outputs/mobile-keyboard-20261101/local';mkdirSync(out,{recursive:true});
const cases=['alfa-a','alfa-b'].flatMap(level=>displayedChapterCollections('paper-dictation',{level,help:'practice'}).map(row=>({level,row,exercise:[...row.exercises].sort((a,b)=>String(b.target).length-String(a.target).length)[0]}))),pictured=cases.find(c=>c.row.id==='route-delen.alfa-b~words-2');assert.equal(cases.length,65);
const route=c=>chapterHash({chapter:'writing',activity:'paper-dictation',collection:c.row.id,level:c.level,help:'practice'}),checks=[],native=[],regression=[],errors=[];
async function measure(p){await p.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));return p.evaluate(()=>{const stage=document.querySelector('.cp-exercise-stage'),nav=document.querySelector('.learner-nav'),navTop=nav&&getComputedStyle(nav).position==='fixed'?nav.getBoundingClientRect().top:innerHeight,selectors=['.cp-view-toggle:nth-child(1)','.cp-view-toggle:nth-child(2)','[data-practice-listen]','.cp-pace-controls>button:nth-child(1)','.cp-pace-controls>button:nth-child(2)','.cp-pace-controls>button:nth-child(3)','.cp-text-entry input','.cp-task-card [data-practice-check]','[data-practice-next]'],rects=selectors.map(selector=>{const e=document.querySelector(selector),r=e.getBoundingClientRect();let clip={left:0,top:0,right:innerWidth,bottom:navTop};for(let a=e.parentElement;a;a=a.parentElement){if(/auto|scroll|hidden|clip/.test(getComputedStyle(a).overflowX+' '+getComputedStyle(a).overflowY)){const q=a.getBoundingClientRect();clip={left:Math.max(clip.left,q.left),top:Math.max(clip.top,q.top),right:Math.min(clip.right,q.right),bottom:Math.min(clip.bottom,q.bottom)};}}return{selector,fullyVisible:r.top>=clip.top-1&&r.left>=clip.left-1&&r.right<=clip.right+1&&r.bottom<=clip.bottom+1,width:r.width,height:r.height};});return{stageHeight:stage.clientHeight,stageContent:stage.scrollHeight,allControlsFullyVisible:rects.every(r=>r.fullyVisible)&&[...document.querySelectorAll('.cp-view-toggle>span')].every(e=>{const a=e.getBoundingClientRect(),b=e.parentElement.getBoundingClientRect();return a.left>=b.left-1&&a.right<=b.right+1&&a.top>=b.top-1&&a.bottom<=b.bottom+1;}),touchTargets44:rects.every(r=>r.width>=44&&r.height>=44),stageFits:stage.scrollHeight<=stage.clientHeight+2,atTop:stage.scrollTop===0&&document.querySelector('.learner-main').scrollTop===0,noHorizontalScroll:document.documentElement.scrollWidth<=innerWidth+1,outerFits:document.querySelector('.learner-main').scrollHeight<=document.querySelector('.learner-main').clientHeight+2,modelFits:[...document.querySelectorAll('.cp-paper-model,.cp-task-card>p')].every(e=>{const r=e.getBoundingClientRect(),s=stage.getBoundingClientRect();return r.top>=s.top-1&&r.bottom<=s.bottom+1&&e.scrollWidth<=e.clientWidth+1;}),rects,oldProgressPreserved:JSON.parse(localStorage.getItem('klink.taalroute.attempts.v1')||'[]').some(a=>a.existing===true)};});}
function check(m,label){for(const k of['allControlsFullyVisible','touchTargets44','stageFits','atTop','noHorizontalScroll','outerFits','modelFits','oldProgressPreserved'])assert(m[k],label+' '+k+' '+JSON.stringify(m));}
async function open(p,c){await p.goto(base+'/#learner/home');await p.locator('.cp-home').waitFor();await p.evaluate(c=>{localStorage.setItem(`klink.group.v1:chapter:paper-dictation:${c.row.id}:paper-dictation`,JSON.stringify({version:1,done:false,exerciseId:c.exercise.exerciseId}));},c);await p.goto(base+'/'+route(c));await p.locator('.cp-pace-controls').waitFor();await p.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);}
for(const[engine,type]of Object.entries({chromium,webkit})){const b=await type.launch();try{
 const p=await b.newPage({viewport:{width:320,height:568},hasTouch:true});p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(()=>{if(!localStorage.getItem('klink.taalroute.attempts.v1'))localStorage.setItem('klink.taalroute.attempts.v1','[{"existing":true}]');window.Audio=class extends EventTarget{play(){this.t=setTimeout(()=>this.dispatchEvent(new Event('ended')),5);return Promise.resolve();}pause(){clearTimeout(this.t);}};});
 for(const c of process.env.KLINK_TEST_ONLINE?[]:cases){await open(p,c);for(const state of['answer','compare','ready']){if(state==='compare'){await p.locator('.cp-text-entry input').fill(String(c.exercise.target));await p.getByRole('button',{name:'Vergelijk',exact:true}).tap();}if(state==='ready')await p.getByRole('button',{name:'Klaar',exact:true}).tap();const m=await measure(p);check(m,engine+' '+c.row.id+' '+state);checks.push({engine,width:320,height:568,id:c.row.id,state,...m});} }await p.close();
 for(const[width,height]of[[390,844],[360,640],[320,568],[740,390]])for(const colorScheme of['light','dark']){const p=await b.newPage({viewport:{width,height},hasTouch:true,colorScheme});p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(()=>{if(!localStorage.getItem('klink.taalroute.attempts.v1'))localStorage.setItem('klink.taalroute.attempts.v1','[{"existing":true}]');window.Audio=class extends EventTarget{play(){this.t=setTimeout(()=>this.dispatchEvent(new Event('ended')),5);return Promise.resolve();}pause(){clearTimeout(this.t);}};});await open(p,pictured);for(const state of['answer','compare','ready']){if(state==='compare'){await p.locator('.cp-text-entry input').fill(String(pictured.exercise.target));await p.getByRole('button',{name:'Vergelijk',exact:true}).tap();}if(state==='ready')await p.getByRole('button',{name:'Klaar',exact:true}).tap();const m=await measure(p);check(m,engine+' '+width+' '+state);checks.push({engine,width,height,colorScheme,id:pictured.row.id,state,...m});if(engine==='chromium'&&colorScheme==='light')await p.screenshot({path:`${out}/${width}-${height}-${state}.png`});}await p.goto(base+'/#learner/home');await p.locator('.cp-home').waitFor();assert(await p.locator('.learner-nav').isVisible());assert(await p.locator('.taalroute-header').isVisible());regression.push({engine,width,height,colorScheme,navigationRestored:true});await p.close();console.log(engine,width,colorScheme,'PASS');}
 const n=await b.newPage({viewport:{width:320,height:568},hasTouch:true});n.on('pageerror',e=>errors.push(e.message));await n.addInitScript(()=>{if(!localStorage.getItem('klink.taalroute.attempts.v1'))localStorage.setItem('klink.taalroute.attempts.v1','[{"existing":true}]');window.ended=[];window.addEventListener('klink-audio-source',e=>{const a=e.detail;a.volume=0;if(a.observed)return;a.observed=true;a.addEventListener('ended',()=>window.ended.push(a.src));});});await n.goto(base+'/'+route(pictured));await n.locator('.cp-pace-controls').waitFor();await n.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);const root=n.locator('[data-exercise-id]'),id=await root.getAttribute('data-exercise-id');await root.locator('h3').focus();await n.keyboard.press('Space');await n.waitForFunction(()=>window.ended.length>0);await n.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);
 for(const label of['6 seconden','9 seconden','Eigen tempo']){await n.getByRole('button',{name:label,exact:true}).tap();assert.equal(await n.getByRole('button',{name:label,exact:true}).getAttribute('aria-pressed'),'true');}await root.locator('h3').focus();await n.keyboard.press('ArrowRight');await n.waitForFunction(id=>document.querySelector('[data-exercise-id]')?.getAttribute('data-exercise-id')!==id,id);await n.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);await n.keyboard.press('ArrowLeft');await n.waitForFunction(id=>document.querySelector('[data-exercise-id]')?.getAttribute('data-exercise-id')===id,id);await n.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);
 const input=n.locator('.cp-text-entry input');await input.fill('test zin');await n.keyboard.press('ArrowLeft');await n.keyboard.press('Space');assert.equal(await input.inputValue(),'test zi n');const exercise=pictured.row.exercises.find(e=>e.exerciseId===id);await input.fill(String(exercise.target));await input.press('Enter');await n.getByRole('button',{name:'Klaar',exact:true}).waitFor();check(await measure(n),engine+' native compare');await n.getByRole('button',{name:'Klaar',exact:true}).tap();await n.waitForFunction(()=>document.querySelector('[data-practice-ready="true"]'));check(await measure(n),engine+' native ready');await root.locator('h3').focus();await n.keyboard.press('Enter');await n.waitForFunction(id=>document.querySelector('[data-exercise-id]')?.getAttribute('data-exercise-id')!==id,id);const stored=await n.evaluate(()=>Object.fromEntries(Object.entries(localStorage).filter(([k])=>k.includes('attempt')||k.startsWith('klink.group.'))));await n.reload();await n.locator('.cp-pace-controls').waitFor();for(const[k,v]of Object.entries(stored))assert.deepEqual(JSON.parse(await n.evaluate(k=>localStorage.getItem(k),k)),JSON.parse(v));native.push({engine,nativePlayback:true,space:true,enter:true,arrows:true,inputTyping:true,touch:true,progressPreserved:true});await n.close();
 }finally{await b.close();writeFileSync(out+'/checks.json',JSON.stringify({base,checks,native,regression,errors},null,2)+'\n');}}
assert.equal(checks.length,process.env.KLINK_TEST_ONLINE?48:438);assert.equal(native.length,2);assert.deepEqual(errors,[]);console.log('PASS',checks.length,'whole-task layouts, 16 navigation checks and 2 native keyboard/audio/progress trials');
